"""Clause-specific R04-R12/executor contracts; final and semantic limits explicit."""
import json,hashlib,time
from pathlib import Path
R=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text('utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def proof(text,prefix,*checks):
 candidates=sorted(p for p in R.glob(prefix+'*/*') if p.name in {'RESULT.json','VERIFICATION.json'})
 assert candidates,prefix
 p=candidates[-1];d=read(p);cs=d.get('checks',{})
 if isinstance(cs,list):cs={c['name']:c['passed'] for c in cs}
 assert checks and all(cs.get(c) is True for c in checks),(prefix,checks)
 return {'criterion':text,'state':'passed_controlled_acceptance','evidence':str(p.relative_to(R)),'evidence_sha256':sha(p),'checks':list(checks)}
def pending(text,reason):return {'criterion':text,'state':'review_required','reason':reason}
